      INTEGER(C_INT), INTENT(out), OPTIONAL :: ierr_
    END SUBROUTINE C_API
  END INTERFACE
  CHARACTER(len=*), INTENT(in) :: fileName
  INTEGER(C_INT), INTENT(out), OPTIONAL :: ierr
  CALL C_API(fileName=istring_(fileName), &
             ierr_=ierr)
END SUBROUTINE gmshWrite

