             strict=optval_c_bool(.FALSE., strict), &
             ierr_=ierr)
  nodeTags = ovectorsize_(api_nodeTags_, &
                          api_nodeTags_n_)
END SUBROUTINE gmshModelMeshGetElementByCoordinates

