  TYPE(C_PTR) :: api_coord_
  INTEGER(C_SIZE_T) :: api_coord_n_
  CALL C_API(elementType=INT(elementType, C_INT), &
             api_localCoord_=localCoord, &
             api_localCoord_n_=size_gmsh_double(localCoord), &
