      REAL(C_DOUBLE), VALUE, INTENT(in) :: meshSize
      INTEGER(C_INT), VALUE, INTENT(in) :: tag
      INTEGER(C_INT), INTENT(out), OPTIONAL :: ierr_
    END FUNCTION C_API
  END INTERFACE
  INTEGER(C_INT) :: gmshModelGeoAddPoint
  REAL(C_DOUBLE), INTENT(in) :: x
  REAL(C_DOUBLE), INTENT(in) :: y
