  REAL(C_DOUBLE), INTENT(in), OPTIONAL :: tol2d
  REAL(C_DOUBLE), INTENT(in), OPTIONAL :: tol3d
  REAL(C_DOUBLE), INTENT(in), OPTIONAL :: tolAng
